    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  /// Свежий запрос первой страницы с базовой валютой проекта (замена списка).
  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();

    _currencyListFuture = currencyRepository.fetchRates(_request(0)).then((CurrencyPage page) {
      final List<CurrencyModel> value = page.items;
      _allCurrencies = value;
      _filteredCurrenciesNotifier.value = value;
      _currentPage = page.page;
      _hasMore = page.hasMore;

      _fadeController.forward(); // запускаем анимацию

      currencyRepository.saveCurrencyList(value);

      return value;
    });
  }

  CurrencyPageRequest _request(int page) => CurrencyPageRequest(
        base: CurrencyListPage.baseCurrency,
        page: page,
        pageSize: _pageSize,
      );

  /// Подгрузка следующей страницы: элементы ДОБАВЛЯЮТСЯ к списку.
  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore) return;

    _isLoadingMore = true;
    try {
      final CurrencyPage page = await context.read<CurrencyRepository>().fetchRates(_request(_currentPage + 1));
      if (!mounted) return;

      final List<CurrencyModel> value = page.items;
      _allCurrencies = <CurrencyModel>[..._allCurrencies, ...value];
      _filteredCurrenciesNotifier.value = _allCurrencies;
      _currentPage = page.page;
      _hasMore = page.hasMore;

      await context.read<CurrencyRepository>().saveCurrencyList(value);
    } finally {
      _isLoadingMore = false;
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

