  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;

  bool _hasMore = false;

  bool _isLoadingMore = false;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _filteredCurrenciesNotifier = ValueNotifier(const []);
    _initData();
