    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  /// Свежий запрос первой страницы с базовой валютой проекта (замена списка).
