4: import 'widgets/widgets.dart';
5: 
6: class CurrencyListPage extends StatefulWidget {
7:   const CurrencyListPage({super.key});
8: 
9:   /// Базовая валюта проекта: default 'EUR' в приложении не используется.
10:   static const String baseCurrency = 'USD';
11: 
12:   @override
13:   State<CurrencyListPage> createState() => _CurrencyListPageState();
14: }
15: 
16: class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
17:   static const int _pageSize = 20;
18: 
19:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
20: 
21:   late final AnimationController _fadeController;
22: 
23:   late Future<List<CurrencyModel>> _currencyListFuture;
24: 
25:   List<CurrencyModel> _allCurrencies = [];
26: 
27:   int _currentPage = 0;
28: 
29:   bool _hasMore = false;
30: 
31:   bool _isLoadingMore = false;
32: 
33:   @override
34:   void initState() {
35:     super.initState();
36:     _initAnimation();
37:     _filteredCurrenciesNotifier = ValueNotifier(const []);
38:     _initData();
39:   }
40: 
41:   @override
42:   void dispose() {
43:     _filteredCurrenciesNotifier.dispose();
44:     _fadeController.dispose();
45:     super.dispose();
46:   }
47: 
48:   void _initAnimation() {
49:     _fadeController = AnimationController(
50:       duration: Duration(milliseconds: 400),
51:       vsync: this,
52:     );
53:   }
54: 
55:   /// Свежий запрос первой страницы с базовой валютой проекта (замена списка).
56:   void _initData() {
57:     final currencyRepository = context.read<CurrencyRepository>();
58: 
59:     _currencyListFuture = currencyRepository.fetchRates(_request(0)).then((CurrencyPage page) {
60:       _applyFirstPage(page);
61: 
62:       _fadeController.forward(); // запускаем анимацию
63: 
64:       currencyRepository.saveCurrencyList(page.items);
65: 
66:       return page.items;
67:     });
68:   }
69: 
70:   /// Обновление при потере фокуса экрана: свежий запрос первой страницы.
71:   void _refresh() {
72:     setState(_initData);
73:   }
74: 
75:   void _applyFirstPage(CurrencyPage page) {
76:     _allCurrencies = page.items;
77:     _filteredCurrenciesNotifier.value = page.items;
78:     _currentPage = page.page;
79:     _hasMore = page.hasMore;
80:   }
81: 
82:   CurrencyPageRequest _request(int page) => CurrencyPageRequest(
83:         base: CurrencyListPage.baseCurrency,
84:         page: page,
85:         pageSize: _pageSize,
86:       );
87: 
88:   /// Подгрузка следующей страницы: элементы ДОБАВЛЯЮТСЯ к списку.
89:   Future<void> _loadMore() async {
90:     if (_isLoadingMore || !_hasMore) return;
91: 
92:     _isLoadingMore = true;
93:     try {
94:       final int nextPage = _currentPage + 1;
95:       final CurrencyPage page = await context.read<CurrencyRepository>().fetchRates(_request(nextPage));
96:       if (!mounted) return;
